&lt;p class="darkgray font13"&gt;
&lt;span class="sender pipe"&gt;&lt;a href="/search?l=blink-dev@chromium.org&amp;q=from:%22%27Taylor+Brandstetter%27+via+blink%5C-dev%22" rel="nofollow"&gt;&lt;span itemprop="author" itemscope itemtype="http://schema.org/Person"&gt;&lt;span itemprop="name"&gt;'Taylor Brandstetter' via blink-dev&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;
&lt;span class="date"&gt;&lt;a href="/search?l=blink-dev@chromium.org&amp;q=date:20260819" rel="nofollow"&gt;Wed, 19 Aug 2026 12:37:12 -0700&lt;/a&gt;&lt;/span&gt;
