&gt;&gt;&gt;&gt;&gt; &lt;&lt;a  rel="nofollow" href="http:///features#tags:quota"&gt;http:///features#tags:quota&lt;/a&gt;&gt;, storage &lt;&lt;a  rel="nofollow" href="http:///features#tags:storage"&gt;http:///features#tags:storage&lt;/a&gt;&gt;
