&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; *&lt;a  rel="nofollow" href="https://github.com/WebKit/standards-positions/issues/541*"&gt;https://github.com/WebKit/standards-positions/issues/541*&lt;/a&gt; 
&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; &lt;&lt;a  rel="nofollow" href="https://nam06.safelinks.protection.outlook.com/?url=https%3A%2F%2Fgithub.com%2FWebKit%2Fstandards-positions%2Fissues%2F541&amp;data=05%7C02%7Cstephanie.zhang%40microsoft.com%7C81a0a04d7bb341a3e49408dea5563241%7C72f988bf86f141af91ab2d7cd011db47%7C1%7C0%7C639129986872130815%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&amp;sdata=d4mAnntEEzmtFS294m9idCHVZOx5CuunvtSl%2FHaHYUE%3D&amp;reserved=0"&gt;https://nam06.safelinks.protection.outlook.com/?url=https%3A%2F%2Fgithub.com%2FWebKit%2Fstandards-positions%2Fissues%2F541&amp;data=05%7C02%7Cstephanie.zhang%40microsoft.com%7C81a0a04d7bb341a3e49408dea5563241%7C72f988bf86f141af91ab2d7cd011db47%7C1%7C0%7C639129986872130815%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&amp;sdata=d4mAnntEEzmtFS294m9idCHVZOx5CuunvtSl%2FHaHYUE%3D&amp;reserved=0&lt;/a&gt;&gt;
&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; )
&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt;
&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; *Web developers*: Positive 
&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; *&lt;a  rel="nofollow" href="https://github.com/w3c/csswg-drafts/issues/4603*"&gt;https://github.com/w3c/csswg-drafts/issues/4603*&lt;/a&gt; 
&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; &lt;&lt;a  rel="nofollow" href="https://github.com/w3c/csswg-drafts/issues/4603"&gt;https://github.com/w3c/csswg-drafts/issues/4603&lt;/a&gt;&gt;: request for 
&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; ranges inside `&lt;textarea&gt;`/`&lt;input&gt;` to support spellchecking/grammar 
